"""Contract test for ExpSmootherFilterTorch, generated by `sensoryforge new-component`.

Calls the same three checks as SensoryForge's own in-repo contract sweep
(`tests/contract/test_component_contracts.py`): a `get_param_spec()` shape
check, one forward pass with the `filter` kind's canonical tensor shape,
and a `from_config(to_dict())` round trip. See
`sensoryforge.testing.contracts.check_component`.
"""

from sensoryforge.testing.contracts import check_component

from sensoryforge_exp_smoother.component import ExpSmootherFilterTorch


def test_exp_smoother_satisfies_component_contract():
    check_component("filter", ExpSmootherFilterTorch)


def test_a_step_rises_by_dt_over_tau_then_towards_the_input():
    import torch

    smoother = ExpSmootherFilterTorch(tau=10.0, dt=1.0)
    out = smoother(torch.ones(1, 3, 1))
    # y1 = 0.1; y2 = 0.1 + (1 - 0.1) / 10 = 0.19; y3 = 0.19 + 0.081 = 0.271.
    assert torch.allclose(out[0, :, 0], torch.tensor([0.1, 0.19, 0.271]))
